def simplify_number(n):
    if n == 1:
        return "1"

    result = []
    i = 0
    while n > 10**i:
        div = (n // (10**(i+1))).bit_length()
        if div > 1:
            result.append("1" + "0" * (div-1) + "^" + str(i) + "^" + str(div-1) + "+")
            n = n // (10**(div-1))
        else:
            result.append(str(n))
            return "".join(result)
        i += 1

