import math

def find(instances):
    sequence = sorted(list(range(1, instances[0] + 1)))
    n, k = instances

    i = sequence[0]
    count, found = 1, 1
    max_visited = 2
    least_ball_get = math.inf

    for i1 in range(1, len(sequence)):
        if sequence[i] - sequence[i1] > 1:
            break
        current_length = sequence[i1] - sequence[i] + 1
        if math.gcd(i1, k) != 1:
            current_length = math.gcd(current_length, k)
        if current_length == 1:
            count += 1

    for i1 in range(n):
        if sequence[i] != i1:
            current1 = sequence[i] - 1
            while True:
                current_value = (sequence[i1] + i1) % n 
                if current_value < n:
                    break
                current_value -= n
                max_visited = max(max_visited, current_value - sequence[i1] + 1)
                least_ball_get = min(least_ball_get, current_value - sequence[i1] + 1)
                current_length = (current_value - sequence[i1] + 1) % k
                if current_length == 1:
                    count -= 1
            if least_ball_get > k:
                break
    return max_visited, least_ball_get + count

