from typing import List, Tuple, Iterable

class Island:
    def __init__(self, id: int, statue_location: int):
        self.id = id
        self.statue_location = statue_location

class BridgeNetwork:
    def __init__(self, bridges: List[Tuple[int, int]], islands: List[Island]):
        self.bridges = set(bridges)
        self.islands = islands

    def get_adjacent_islands(self, island_id: int) -> Iterable[int]:
        for src, dst in self.bridges:
            if src == island_id:
                yield dst
            elif dst == island_id:
                yield src

    def is_adjacent(self, island1: int, island2: int) -> bool:
        for src, dst in self.bridges:
            if src == island1 and dst == island2:
                return True
        return False

    def connect_islands(self, island1: int, island2: int, statue_id1: int, statue_id2: int) -> Tuple[int, int, int]:
        self.bridges.add((island1, island2))
        movement_count = 2
        if statue_id1 > statue_id2:
            min_movement = abs(statue_id1 - statue_id2) + 1
        else:
            min_movement = statue_id1 - statue_id2
        return statue_id1, min_movement

    def connect_island_to_empty(self, island_id: int, target_id: int) -> Tuple[int, int, int]:
        for adjacent_island in self.get_adjacent_islands(island_id):
            if self.is_adjacent(island_id, adjacent_island) and self.bridges.intersection([(adjacent_island, target_id)]):
                statue_id, movement_count = target_island, 1
                return statue_id, movement_count
        return -1, 0

def rearrange_statues(network: BridgeNetwork, current_statues: List[int], goal_statues: List[int]) -> Tuple[int, int, int]:
    u, v = None, None
    for i in range(1, len(network)):
        current_loc, goal_loc = current_statues[i - 1], goal_statues[i]
        statue_to_move, distance = network.connect_island_to_empty(i, network.statue_location[i])
        if statue_to_move > 0:
            u, v = network.statue_location[i], network.statue_location[goal_loc]
        return u, v, statue_to_move

# Example usage:
