def find_key(p, s, k):
    if k > len(s):
        return "0"

    dp = [[False] * 2 for _ in range(k+1)]
    dp[0][0] = True
    for i in range(1, len(s)):
        dp[i][0] = True if i + 1 in range(k+1) and dp[i-1][0] else False

    for i in range(1, k+1):
        for j in range(1, 26):
            dp[i][j] = dp[i-1][j] and s[0].islower() or s[0].isupper() and dp[i-1][j-1] or dp[i-1][j]

    for i in range(1, k+1):
        if dp[k][i]:
            return '1' if i % 26 == 0 else '0'
    return '0'

