from functools import lru_cache

def max_f_value(n, a):
    @lru_cache(maxsize=None)
    def dp(curr, mod):
        if curr == n:
            return 0
        max_f = float('-inf')
        for i in range(1, len(a) + 1):
            max_f = max(max_f, (a[curr] * i) % mod + dp(curr + 1, (mod*i) % mod))
        return max_f

    mod = 10**9 + 9
    return max(dp(i, (mod*i) % mod) for i in range(1, n + 1))

