                    successor = tuple(max(it.complement(component_diameters), key=len))
                    component_queries = queries_data.get(predecessor, []) + [queries_data.get(predecessor, []), (a, b)] + queries_data.get(successor, [])
                    component_diameters_a = component_diameters.get(predecessor, {})
                    component_diameters_b = component_diameters.get(successor, {})
                    for query_data in [component_diameters_a, component_diameters_b]:
                        for k, v in component_queries.items():
                            queries_data.setdefault(k, []).extend(v)

            queries_data[a, b] = queries_data.get((a, b), []) + [(i, conn) for conn in edges]
        # Add the edge found
        else:
            edges.append(connections[i])
            queries_data[(a,b)] = [(i, connections[i])]

    # Initial queries to the tree
    for a, b in itertools.combinations(connections[0] + list(queries[0][1]), 2):
        queries_data[a, b] = [i for i, conn in enumerate(edges)]  # a parent, b child

    queries_data = {a: {i + 1} for (a, b), i in queries_data.items()}  # Convert dict to a list for easy lookup
    component_diameters = {a: {b} for a, b in queries_data}  # Set from the first component to this

    for i in range(len(edges)):
        a, b = edges[i]
        for aPos, bPos in queries_data[a, b]:  # only pos in this component
            component_diameters[aPos][bPos] = queries_data[a, b][aPos][1] - 1
        if len(component_diameters[a]) > 1 or len(component_diameters[b]) > 1:
            for aPos, component_size in component_diameters[a].items():
                for bPos, component_size in component_diameters[a].items():
                    if aPos != bPos:
                        component_diameter = max(component_size - 1, component_diameters[b].get(bPos, component_size))
                        component_diameters[aPos][bPos] = component_diameter

    result = 0
    for aQ in component_diameters:
        for bQ in component_diameters:
            if (aQ, bQ) in component_diameter_query_counts:
                result += component_diameter_query_counts[(aQ, bQ)]

    return result/len(queries_data.values())

