def calculate_jump_time(xi, xi_left, xi_right, ci, di, bi, ai):
    """
    Calculate the total time for a jump from xi to the closest movable (= less than xi) chair.
    """
    non_large_cost = 0
    large_cant_jump = False
    small_can_jump = True
    for xj in (xi_left, xi_right):
        if large_cant_jump or small_can_jump:
            if xj < xi:
                non_large_cost += xj - xi + ci
            elif xj > xi:
                non_large_cost += abs(xj - xi) + di
        elif xj <= xi:
            large_cant_jump = True
        else:
            small_can_jump = False
    return non_large_cost

