# function to convert a binary string to its corresponding index
def binary_to_index(binary_str):
    return int(binary_str, 2)

# function to check if the key exists based on the given container, message, and key length
def check_key(p, s, key_length):
    i = 0
    j = 0
    s_index = 0
    key = ''

    while i < len(p) and j < len(s):
        if s[j] == '1':
            s_index = binary_to_index(s) & (2**(key_length - 1) - 1)
            key += '1'
        else:
            s_index = binary_to_index(s) & (2**(key_length - 1))
            key += '0'
        if j == len(s) - 1:
            j = 0
        else:
            j += 1

    return binary_to_index(s_index).to_bytes(1, byteorder='big') == p[i:i+key_length]

# main function to find the lexicographically minimum key
def find_min_key(p, s, key_length):
    if len(p) < key_length:
        return '0' * key_length

    for i in range(1, 257):
        if check_key(p, s, i):
            return find_min_key(p, s, i - 1)
    return '0' * key_length

