from typing import List

def calculate_min_max_gift_givers(n: int, k: int, p: List[int]) -> List[int]:
    gifts = [p[i] for i in range(1, n+1)]
    count = [0] * (n + 1)
    for i in range(n):
        count[gifts[i]] += 1

    min_gift_givers = sum(count[-1] for _ in range(n - k))
    max_gift_givers = count[0]

    # Check for the case where we might break the dependency constraints placing fewer gifts outside the dependency cycle
    for e in range(1, n // 2 + 1):
        cycle_size = count[e]
        temp_count = count[e-1] + cycle_size - k
        if temp_count <= len(count):
            temp_count -= 1

        for e in range(1, n // 2 + 1):
            cycle_size = count[n-e]
            temp_count = count[n-e-1] + cycle_size - k
            if temp_count <= len(count):
                temp_count -= 1

            for _ in range(count[e-1] + cycle_size - 1):
                paired_index = (1 + (-(e-1)) * (n+1)) % ((-(n+1)-1) + 1) 
                if paired_index != 0 and count[paired_index] < temp_count:
                    break
            else:
                pair = paired_index
                break
        else:
            continue
        if count[pair-1] + cycle_size - 1 <= len(count) or temp_count <= len(count):
            break

    return [min_gift_givers, max_gift_givers]

