import sys

def find_path(graph, start, end):
    visited = [False] * len(graph)
    stack = [(start, 0)]

    while stack:
        current, cost = stack.pop()
        if current == end:
            return cost
        if visited[current]:
            continue
        visited[current] = True
        for neighbor in range(len(graph)):
            if graph[current][neighbor] > 0 and not visited[neighbor]:
                stack.append((neighbor, cost + graph[current][neighbor]))
        graph[current] = [-1] * len(graph)  # Dijkstra's like, set all values to -1 (Dijkstra's bring back the shortest path)

    raise ValueError('There is no path between the nodes')

def rearrange_statues(islands, rev_islands, building_connection, start_degree):
    dp = [sys.maxsize] * (start_degree + 1)
    dp[0] = 0

    for i in range(start_degree + 1):
        for neighbor in range(len(building_connection)):
            if rev_islands[start_degree - i - 1] not in islands[neighbor]:
                if dp[neighbor] > dp[start_degree - i] + find_path(islands, rev_islands[start_degree - i - 1],
                                                                  buildings[i], 0):
                    dp[neighbor] = dp[start_degree - i] + find_path(islands, rev_islands[start_degree - i - 1],
                                                                   buildings[i], 0)

    minimum_moves = dp[start_degree]
    from_node = end_node = -1

    for i in range(start_degree + 1):
        for neighbor in range(len(building_connection)):
            if rev_islands[buildings[i]][(i + 1) % len(buildings[i])] not in islands[neighbor]:
                if dp[neighbor] == minimum_moves:
                    from_node = buildings[i]
                    to_node = i + 1

    if from_node < 0:
        return -1
    if from_node == end_node:
        return dp[from_node]
    else:
        return dp[from_node] + dp[end_node] + building_connection[from_node][to_node]

