def floyd_warshall(G):
    V = len(G)

    for k in range(1, V+1):
        for i in range(1, V+1):
            for j in range(1, V+1):
                G[i][j] = min(G[i][j], G[i][k] + G[k][j])

    edges_sum = 0
    for i in range(1, V+1):
        for j in range(1, V+1):
            if i != j:
                edges_sum += G[i][j]

    return edges_sum
