    data = input().split()
    n = int(data[0])
    if n == 1:
        return data

    r = list(map(int, data[1:]))
    amphoras = defaultdict(list)
    for i, r_i in enumerate(r):
        for j in range(1, min(i, r_i + 1) + 1):
            amphoras[i-j].append(r_i)

    processes = list(amphoras.values())
    processes.sort()

    for k in processes:
        processes.sort(key=lambda x: -x)

    seconds = [0] * n
    for i, r_i in enumerate(r):
        for prev in amphoras[i-r_i]:
            seconds[i-1] = max(seconds[i-1], seconds[prev])
        seconds[i-1] += len(processes) + 1
        amphoras.pop(i-r_i)

    amphoras = defaultdict(list)
    start = max(seconds)
    for i, r_i in enumerate(r):
        for j in range(1, min(i, r_i + 1) + 1):
            amphoras[i-j].append(start + seconds[i-1])
        amphoras.pop(i-r_i)

    seconds = []
    processes_sorted = sorted(list(amphoras.values()))
    processes_sorted.sort()

    k = -1
    for val in processes_sorted:
        if k != val:
            k = val
        for i in range(len(seconds)):
            jk = k if k <= i else i + 1
            seconds[i] = max(seconds[i], jk - k + 1)

