import sys

def add_edges(s, t):
    return "{} -> {}\n".format(s + 1, t + 1)

def find(parent, i):
    if parent[i] == -1:
        return i
    return find(parent, parent[i])

def union(parent, rank, a, b):
    rootA = find(parent, a)
    rootB = find(parent, b)
    if rootA != rootB:
        if rank[rootA] < rank[rootB]:
            parent[rootA] = rootB
        elif rank[rootA] > rank[rootB]:
            parent[rootB] = rootA
        else:
            parent[rootB] = rootA
            rank[rootA] += 1

def kruskal(m, n, edges):
    parent = [-1] * (n + 1)
    rank = [0] * (n + 1)
    minimum_spanning_tree = []

    for i in range(1, n + 1):
        parent[i] = i

    for edge in edges:
        u, v = edge
        if find(parent, u) != find(parent, v):
            union(parent, rank, u, v)
            minimum_spanning_tree.append(edge)

    total_weight = 0
    for i in range(1, n + 1):
        if parent[i] == i:
            total_weight += 1

    return total_weight, minimum_spanning_tree

def enlarge(mocha_edges, diana_edges, n):
    m_total, mocha_m_tree = kruskal(len(mocha_edges), n, mocha_edges)
