                        n // 2:
                    ]
                    used_beads = set()

                    # Fill in bracket right half.
                    for c2 in range(n // 2):
                        if beads[bracket_right - c2] not in used_beads:
                            used_beads.add(beads[bracket_right - c2])
                    if len(used_beads) == n // 4:
                        if max_cuts < max(
                            n // 4 - 1,
                            len(beads) / 2 + n * 2 / 3,
                        ):
                            max_cuts = max(
                                n // 4 - 1,
                                len(beads) / 2 + n * 2 / 3,
                            )
    return max_cuts

