import math

def simplify_number(n):
    def prime_factors(n):
        i = 2
        factors = []
        while i * i <= n:
            if n % i:
                i += 1
            else:
                n //= i
                factors.append(i)
        if n > 1:
            factors.append(n)
        return factors

    def normalize_factors(factors):
        from functools import reduce
        return str(reduce(lambda x, y: x * y, factors))

    factors = prime_factors(n)
    if len(factors) == 1:
        return "1" if factors[0] == 1 else factors[0]
    first = str(factors[0])
    for i in range(1, len(factors)):
        if factors[i] % factors[0] == 0:
            first += "*" if first == "*" else "+"
        first += "^" if i == 1 else ""
    return normalize_factors(eval(first))

n = int(input())
print(simplify_number(n))
