from collections import Counter

def max_beautiful_cuts(colors):
    seq = Counter(colors)
    max_cuts = 0
    for k, v in seq.items():
        if k >= 4:
            max_cuts += v
            v = 0
        else:
            max_cuts += 2 * v
        if k > 1:
            max_cuts += k // 2

    # Ensure we don't use more colors than available
    max_cuts_supported = 0
    for k, v in colors.items():
        if k <= 1 and seq[k] > 0:
            max_cuts_supported += 1
        elif k > 1 and seq[k] > 0:
            max_cuts_supported += v // 2

    return max_cuts_supported

# Example usage
colors = Counter({1: 4, 2: 2, 3: 1})
max_cuts = max_beautiful_cuts(colors)
